   645
   646  uint8_t NcpBase::GetWrappedResponseQueueIndex(uint8_t aPosition)
   647  {
   648      while (aPosition >= kResponseQueueSize)
   649      {
   650          aPosition -= kResponseQueueSize;
   651      }
   652
   653      return aPosition;
   654  }
   655
   656  otError NcpBase::EnqueueResponse(uint8_t aHeader, ResponseType aType, unsigned int aPropKeyOrStatus)
   657  {
   658      otError        error = OT_ERROR_NONE;
   659      spinel_tid_t   tid   = SPINEL_HEADER_GET_TID(aHeader);
   660      ResponseEntry *entry;
   661
   662      if (tid == 0)
   663      {
   664          // No response is required for TID zero. But we may emit a
   665          // `LAST_STATUS` error status (if not filtered) for TID
   666          // zero (e.g., for a dropped `STREAM_NET` set command).
   667
   668          if (aType == kResponseTypeLastStatus)
   669          {
   670              mChangedPropsSet.AddLastStatus(static_cast<spinel_status_t>(aPropKeyOrStatus));
   671          }
   672
   673          ExitNow();
   674      }
   675
   676      if ((mResponseQueueTail - mResponseQueueHead) >= kResponseQueueSize)
   677      {
   678          // If there is no room a for a response, emit an unsolicited
   679          // `DROPPED` error status to indicate a spinel response was
   680          // dropped.
   681
   682          mChangedPropsSet.AddLastStatus(SPINEL_STATUS_DROPPED);
   683
   684          ExitNow(error = OT_ERROR_NO_BUFS);
   685      }
   686
   687      // Transaction IDs are expected to come in sequence, if however, we
   688      // get an out of sequence TID, check if we already have a response
   689      // queued for this TID and if so mark the old entry as deleted.
   690
   691      if (tid != mNextExpectedTid)
   692      {
   693          for (uint8_t cur = mResponseQueueHead; cur < mResponseQueueTail; cur++)
   694          {
   695              entry = &mResponseQueue[GetWrappedResponseQueueIndex(cur)];
   696
   697              if (entry->mIsInUse && (entry->mTid == tid))
   698              {
   699                  // Entry is just marked here and will be removed
   700                  // from `SendQueuedResponses()`.
   701
   702                  entry->mIsInUse = false;
   703                  break;
   704              }
   705          }
   706      }
   707
   708      // Add the new entry in the queue at tail.
   709
   710      entry = &mResponseQueue[GetWrappedResponseQueueIndex(mResponseQueueTail)];
   711
   712      entry->mTid             = tid;
   713      entry->mIsInUse         = true;
   714      entry->mType            = aType;
   715      entry->mPropKeyOrStatus = aPropKeyOrStatus;
   716
   717      mResponseQueueTail++;
   718
   719  exit:
   720      return error;
